// Validar datos de entrada
const body = $input.first().json.body;

if (!body) {
  throw new Error('No se recibieron datos');
}

if (!body.characters || !Array.isArray(body.characters) || body.characters.length === 0) {
  throw new Error('Debe incluir al menos un personaje');
}

if (!body.setting) {
  throw new Error('Debe incluir un lugar');
}

if (!body.storyType) {
  throw new Error('Debe incluir un tipo de historia');
}

// Preparar datos validados
return {
  json: {
    characters: body.characters,
    setting: body.setting,
    storyType: body.storyType,
    childName: body.childName || 'el niño',
    childAge: body.childAge || 8,
    timestamp: body.timestamp || new Date().toISOString()
  }
};

