// Obtener respuesta de ChatGPT
const chatResponse = $input.first().json.message.content;

console.log('📥 Respuesta de OpenAI:', chatResponse);

// Parsear JSON
let storyData;
try {
  // Limpiar la respuesta de posibles markdown
  const cleanResponse = chatResponse
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();

  console.log('🧹 Respuesta limpia:', cleanResponse);

  storyData = JSON.parse(cleanResponse);

  // Validar que tenga los campos necesarios
  if (!storyData.title || !storyData.story) {
    throw new Error('Respuesta incompleta de OpenAI');
  }

  console.log('✅ JSON parseado correctamente');

} catch (error) {
  console.error('❌ Error al parsear JSON:', error.message);
  console.error('📄 Respuesta original:', chatResponse);

  // Fallback: usar la respuesta como texto plano
  storyData = {
    title: "Historia Mágica",
    story: chatResponse,
    imagePrompt: "Una escena mágica de un cuento infantil"
  };
}

// Retornar datos estructurados
const result = {
  title: storyData.title,
  content: storyData.story,
  imagePrompt: storyData.imagePrompt || "Una escena mágica de un cuento infantil",
  imageUrl: "",
  timestamp: new Date().toISOString(),
  success: true
};

console.log('📤 Respuesta final:', result);

return { json: result };

// Capturar el error
const error = $input.first().json.error || {};
const errorMessage = error.message || 'Error desconocido';

console.error('🚨 Error en el workflow:', errorMessage);
console.error('📦 Error completo:', JSON.stringify(error, null, 2));

// Determinar el tipo de error
let userMessage = 'Error al generar la historia';
let errorType = 'unknown';

if (errorMessage.includes('API key')) {
  userMessage = 'Error con la API Key de OpenAI';
  errorType = 'api_key';
} else if (errorMessage.includes('quota') || errorMessage.includes('insufficient_quota')) {
  userMessage = 'Créditos de OpenAI agotados';
  errorType = 'quota';
} else if (errorMessage.includes('rate limit')) {
  userMessage = 'Demasiadas peticiones a OpenAI';
  errorType = 'rate_limit';
} else if (errorMessage.includes('timeout')) {
  userMessage = 'Tiempo de espera agotado';
  errorType = 'timeout';
}

return {
  json: {
    success: false,
    error: true,
    message: userMessage,
    errorType: errorType,
    details: errorMessage,
    timestamp: new Date().toISOString()
  }
};
